package com.booksyde.controller; import com.booksyde.dto.request.*; import com.booksyde.dto.response.*; import com.booksyde.service.CommunityService; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/community") public class CommunityController {private final CommunityService s;public CommunityController(CommunityService s){this.s=s;} @GetMapping("/works/{id}/comments") public List<CommentResponse> comments(@PathVariable UUID id,@RequestParam(required=false) UUID volumeId){return s.comments(id,volumeId);} @PostMapping("/works/{id}/comments") public CommentResponse add(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody CommentRequest r){return s.addComment(j,id,r);} @PutMapping("/comments/{id}") public CommentResponse edit(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody CommentRequest r){return s.editComment(j,id,r);} @DeleteMapping("/comments/{id}") public void del(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){s.deleteComment(j,id);} @GetMapping("/works/{id}/reviews") public List<ReviewResponse> reviews(@PathVariable UUID id){return s.reviews(id);} @PutMapping("/works/{id}/reviews/me") public ReviewResponse review(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody ReviewRequest r){return s.saveReview(j,id,r);} @DeleteMapping("/works/{id}/reviews/me") public void delReview(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){s.deleteReview(j,id);}}